def subtract(a, b):
    # Filter out empty intervals (start >= end)
    a = [interval for interval in a if interval[0] < interval[1]]
    b = [interval for interval in b if interval[0] < interval[1]]

    # If a is empty, return empty list
    if not a:
        return []

    # If b is empty, merge and return a
    if not b:
        return merge_intervals(a)

    # Merge intervals in a and b separately
    a_merged = merge_intervals(a)
    b_merged = merge_intervals(b)

    # Subtract b from a
    result = []
    for a_start, a_end in a_merged:
        current_start = a_start
        for b_start, b_end in b_merged:
            if b_end <= current_start:
                # b interval is completely before current segment
                continue
            if b_start >= a_end:
                # b interval is completely after current segment
                break
            if b_start > current_start:
                # Add the part before b
                result.append([current_start, b_start])
            # Move current_start past the b interval
            current_start = max(current_start, b_end)
            if current_start >= a_end:
                # Rest of a is covered by b
                break
        if current_start < a_end:
            # Add remaining part
            result.append([current_start, a_end])

    return result


def merge_intervals(intervals):
    if not intervals:
        return []

    # Sort by start position
    sorted_intervals = sorted(intervals, key=lambda x: x[0])

    merged = [sorted_intervals[0]]
    for current in sorted_intervals[1:]:
        last = merged[-1]
        if current[0] <= last[1]:
            # Overlapping or touching, merge them
            merged[-1] = [last[0], max(last[1], current[1])]
        else:
            # Non-overlapping, add as new interval
            merged.append(current)

    return merged

